 dict(id='gate 2a',claim='the recomputed blocking effect E_rec is certified',estimand='E_rec (nat/token)',test='t and exact sign-flip, one-sided; mean >= .25',level=.05,gate='-',if_significant='E_rec is certified'),
 dict(id='gate 2b',claim='the recomputed band effect E_mask is certified',estimand='E_mask (nat/token)',test='t and exact, one-sided; mean >= .10',level=.05,gate='2a',if_significant='E_mask is certified'),
 dict(id='gate 2c',claim='the masked update has a positive margin effect G',estimand='G (nat/fact)',test='t and exact, one-sided',level=.05,gate='2a',if_significant='G > 0'),
