 dict(id='3b',claim='3a and the recomputed band effect explains the recomputed oracle effect',estimand='T_Q = E_rec - .7 E_mask > 0',test='t and exact, one-sided',level=.05,gate='2a, 2b, 3a',if_significant='R-leak and Q'),
